INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 1, 'Watermelon Gin & Tonic', 'A light and breezy summer tonic made with daily fresh cold-pressed watermelon juice, craft gin, and dry tonic water, garnished with frozen watermelon cubes.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 2, 'Earl Grey Sour', 'Bright and aromatic citrus sour balancing Earl Grey infused gin with tangy fresh lemon, wildflower honey, and fresh apple juice.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 3, 'Oolong Old Fashioned', 'A bold, slow-sipping craft cocktail highlighting premium American bourbon whiskey cold-steeped with high-mountain Alishan oolong tea leaves.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 4, 'Passion Fruit Daiquiri', 'Tropical tartness combining white Caribbean rum, lime, fresh local passion fruit pulp, and crushed Magao (wild mountain pepper) seeds.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 5, 'Guava Cooler', 'Sweet pink local guava juice shaken with light rum, lime, and a refreshing house-infused cucumber and kaffir lime leaf syrup.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 6, 'Sour Plum Soup Whiskey Sour', 'Rich Taiwanese-inspired sour using whiskey infused with slow-cooked sour plum soup (Suanmeitang), finished with fresh lemon, simple syrup, bitters, and a spritz of smoky Islay malt.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 7, 'Chocolate Negroni', 'Luxurious digestif mixing rich VSOP Cognac, house-prepared dark cacao liqueur, Triple Sec orange liqueur, and Campari.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 8, 'Umabee', 'Elegantly sweet cocktail shaking dry gin with fresh lemon, concentrated sparkling wine reduction, and finished with organic bee pollen.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 9, 'Absinthe Emerald', 'An intense, herbaceous performance blending gin, absinthe, fresh lemon juice, Japanese yuzu kosho, and fresh muddled shiso leaves.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 10, 'El Diablo Verde', 'Smoky, spicy mezcal cocktail featuring Durango mezcal, fresh lime, sliced green jalapeño chili, and Merlet Crème de Cassis blackcurrant liqueur.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 11, 'Niaoli Calvados', 'Elegant local hybrid featuring apple eau de vie, lemon, and sweet candied Taiwanese bird pear (Niaoli).');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 12, 'Smoke Zest & Pepper', 'A bold, smoke-forward creation featuring artisanal Amaras Verde Mezcal, balanced by fresh lime acidity and the bright, spicy kick of calamansi and white pepper.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 13, 'House Salsa & Nachos', 'Crisp corn tortilla nachos served with fresh house-made tomato, cilantro, and onion salsa.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 14, 'Brown Sugar Roasted Nuts', 'Assorted nuts slow-roasted in-house with Taiwanese brown sugar and aromatic spices.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 15, 'Homemade Duck Prosciutto', 'Thinly sliced premium duck breast cured and wind-dried in-house for intense savory flavor.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 16, 'Nachos Platter', 'Large sharing platter of corn tortilla chips baked with melted cheese, jalapeños, salsa, and sour cream.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 17, 'Roasted Chicken Wrap', 'Grilled chicken breast wrap packed with fresh vegetables and creamy yogurt dressing.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 18, 'Cured Salmon on Sour Cream Toast', 'House-cured Atlantic salmon slices served over toasted sourdough bread spread with dill sour cream.');
