INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 27, 'RED POINT TaiPA 5.8% alc.', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 28, 'Dirty Martini', 'A savory, dry favorite shaking gin with dry vermouth, green olive brine, and garnished with olives.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 29, 'Espresso Martini', 'A rich, energizing cocktail of triple-distilled vodka, freshly pulled espresso coffee, brown sugar, and house-made coffee amaro.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 30, 'Paloma', 'Bright and effervescent tequila cooler mixing blue agave tequila, fresh lime juice, pink grapefruit juice, a splash of Campari, and carbonated water.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 31, 'Clover Club', 'A pre-prohibition classic combining gin, lemon juice, fresh raspberries, dry vermouth, and egg whites for a silky finish.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 32, 'Bloody Mary', 'A spicy, savory meal in a glass: vodka, lime, rich tomato juice, house seasoning blend (Worcestershire sauce, Tabasco, peppercorns).');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 33, 'Pina Colada', 'Tropical paradise of light rum, lime juice, pineapple juice, and rich sweet coconut cream blended until smooth.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 34, 'Moscow Mule', 'A crisp and refreshing highball blending clean vodka, zesty fresh lime juice, and spicy ginger beer.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 35, 'Penicillin', 'Soothing blend of blended Scotch whiskey, fresh lemon, ginger-honey syrup, finished with a float of peated smoky Islay malt.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 36, 'Pisco Sour', 'The Peruvian classic shaking pisco brandy with fresh lime juice, simple syrup, egg whites, and finished with aromatic Amargo Chuncho bitters.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 37, 'Sazerac', 'An iconic New Orleans classic blending rich rye whiskey with sweet simple syrup, aromatic Peychaud''s bitters, and a mysterious rinse of absinthe.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 38, 'Sidecar', 'A sophisticated, sour-leaning classic featuring premium Cognac, citrusy Cointreau orange liqueur, and fresh lemon juice.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 39, 'Vieux Carre', 'A complex, spirit-forward tribute to New Orleans, combining rye whiskey, smooth VSOP Cognac, sweet vermouth, Bénédictine herbal liqueur, and bitters.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 40, 'Death in the Afternoon', 'A potent, effervescent creation invented by Ernest Hemingway, mixing white absinthe with crisp Champagne.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 41, 'House Spirit', 'Full bottle of our premium house spirit select from Vodka, Gin, Bourbon Whiskey, Light Rum, or Silver Tequila.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 42, 'House Red / White', 'Select bottle of our carefully sourced house red or house white wine.');
