INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 55, 'Balvenie Double Wood 12 years', 'Classic Speyside single malt aged in traditional oak then finished in sherry casks.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 56, 'Balvenie Port Wood 21 years', 'Magnificent single malt finished in high-quality port pipes, adding deep fruit tones.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 57, 'Macallan 15 years', 'Exquisite double cask single malt aged in sherry-seasoned American and European oak.');
