INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 59, 'Don Julio Reposado', 'Golden tequila aged for 8 months in white oak barrels, with citrus and spice notes.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 60, 'Don Julio Añejo', 'Rich tequila aged for 18 months, with complex caramel, wild honey, and oak notes.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 61, 'Don Julio 1942', 'Iconic, ultra-premium tequila aged in small batches, tasting of warm caramel and vanilla.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('en', 'menu_item', 62, 'Clase Azul Reposado', 'Legendary reposado tequila housed in a hand-painted ceramic decanter.');
