INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 1, 'Watermelon Gin & Tonic', 'Un gin tonic d''été frais et léger fait avec du jus de pastèque frais pressé quotidiennement, du gin artisanal, du tonic dry, et garni de cubes de pastèque congelés.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 2, 'Earl Grey Sour', 'Un cocktail acidulé et floral équilibrant le gin infusé à l''Earl Grey avec du citron jaune frais, du miel sauvage et du jus de pomme fraîchement pressé.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 3, 'Oolong Old Fashioned', 'Un cocktail corsé à savourer lentement, mettant en valeur un bourbon américain vieilli infusé à froid avec des feuilles de thé oolong des montagnes d''Alishan.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 4, 'Passion Fruit Daiquiri', 'Une acidité tropicale alliant rhum blanc des Caraïbes, citron vert, pulpe de fruit de la passion locale et graines de poivre Magao de montagne broyées.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 5, 'Guava Cooler', 'Jus de goyave rose locale secoué avec du rhum léger, du citron vert, et un sirop rafraîchissant maison de concombre et feuilles de combava.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 6, 'Sour Plum Soup Whiskey Sour', 'Un cocktail acidulé d''inspiration taïwanaise avec du whisky infusé à la soupe traditionnelle de prunes acides (Suanmeitang), citron, sirop simple, bitters, et une touche de whisky d''Islay fumé.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 7, 'Chocolate Negroni', 'Un digestif luxueux mélangeant du Cognac VSOP, de la liqueur de cacao noir maison, du Triple Sec et du Campari.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 8, 'Umabee', 'Un cocktail doux et floral secouant du gin avec du citron frais, du concentré de vin pétillant réduit, le tout saupoudré de pollen d''abeille bio.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 9, 'Absinthe Emerald', 'Un cocktail puissant et herbacé mêlant du gin, de l''absinthe, du citron jaune frais, du yuzu kosho japonais et des feuilles de shiso fraîches pilées.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 10, 'El Diablo Verde', 'Cocktail de mezcal fumé et épicé avec du mezcal Durango, du citron vert, du piment jalapeño frais et de la crème de cassis Merlet.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 11, 'Niaoli Calvados', 'Cocktail élégant mariant de l''eau-de-vie de pomme, du citron, et des petites poires taïwanaises caramélisées maison (Niaoli).');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 12, 'Smoke Zest & Pepper', 'Une création audacieuse et fumée mettant en valeur le mezcal artisanal Amaras Verde, équilibrée par l''acidité du citron vert frais et la touche vive et épicée du calamansi et du poivre blanc.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 13, 'House Salsa & Nachos', 'Nachos de maïs croustillants servis avec notre salsa maison fraîche à base de tomates, coriandre et oignons.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 14, 'Brown Sugar Roasted Nuts', 'Mélange de noix rôties lentement sur place avec du sucre roux taïwanais et des épices aromatiques.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 15, 'Homemade Duck Prosciutto', 'Magret de canard de qualité supérieure séché et affiné sur place pour une saveur salée intense.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 16, 'Nachos Platter', 'Grand plateau de nachos de maïs cuits au four avec du fromage fondu, des jalapeños, de la salsa et de la crème sure.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 17, 'Roasted Chicken Wrap', 'Wrap de blanc de poulet grillé avec des légumes frais croquants et une sauce au yaourt crémeuse.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 18, 'Cured Salmon on Sour Cream Toast', 'Tranches de saumon atlantique mariné maison servies sur du pain au levain grillé avec de la crème sure à l''aneth.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 19, 'APPLE OSMANTHUS', NULL);
