INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 28, 'Dirty Martini', 'Un grand classique sec et salé associant du gin, du vermouth dry et de la saumure d''olive verte.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 29, 'Espresso Martini', 'Un cocktail riche et énergisant à base de vodka, d''espresso fraîchement extrait, de sucre roux et d''un amaro au café maison.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 30, 'Paloma', 'Cocktail rafraîchissant à base de tequila d''agave bleu, jus de citron vert frais, jus de pamplemousse rose, un trait de Campari et eau pétillante.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 31, 'Clover Club', 'Un classique datant d''avant la prohibition mêlant gin, jus de citron, framboises fraîches, vermouth dry et blanc d''œuf pour une finale veloutée.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 32, 'Bloody Mary', 'Un classique salé et épicé : vodka, citron vert, jus de tomate riche, et notre mélange d''épices maison (Worcestershire, Tabasco, poivre noir).');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 33, 'Pina Colada', 'Un délice tropical mariant rhum léger, jus de citron vert, jus de menthe ou de fruits frais, et crème de noix de coco sucrée.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 34, 'Moscow Mule', 'Un highball rafraîchissant combinant de la vodka pure, du jus de citron vert frais et de la bière de gingembre épicée.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 35, 'Penicillin', 'Mélange apaisant de Scotch whisky, citron frais, sirop de miel et de gingembre, couronné de Scotch d''Islay tourbé et fumé.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 36, 'Pisco Sour', 'Le classique péruvien mariant l''eau-de-vie de pisco avec du citron vert frais, du sirop simple, du blanc d''œuf et quelques gouttes de bitters aromatiques Amargo Chuncho.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 37, 'Sazerac', 'Un classique légendaire de la Nouvelle-Orléans mêlant le caractère épicé du whiskey de seigle avec du sirop de sucre, des bitters Peychaud et un rinçage à l''absinthe.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 38, 'Sidecar', 'Un cocktail acidulé classique et sophistiqué associant du Cognac VSOP Merlet avec du Cointreau et du jus de citron jaune frais.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 39, 'Vieux Carré', 'Un hommage riche et complexe à la Nouvelle-Orléans, mariant whiskey de seigle, Cognac VSOP Merlet, vermouth rouge doux, Bénédictine et bitters.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 40, 'Death in the Afternoon', 'Une création puissante inventée par Ernest Hemingway, alliant la fraîcheur herbacée de l''absinthe blanche avec du Champagne brut.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 41, 'Bouteille Alcool Maison', 'Bouteille entière de notre gamme d''alcool maison au choix : Vodka, Gin, Bourbon, Rhum ou Tequila.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 42, 'Bouteille de Vin Maison', 'Sélection de notre bouteille de vin rouge ou blanc maison.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 43, 'Château Edmus St Émilion 2013', 'Grand Cru de Bordeaux de Saint-Émilion, rond et élégant, dominé par le Merlot.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 44, 'Les Bellissands 1er Cru 2018', 'Vin rouge de Bourgogne fin et délicat, cépage Pinot Noir, issu d''une parcelle premier cru.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 45, 'Pouilly Fuissé 2018', 'Vin blanc sec et élégant de Bourgogne issu du cépage Chardonnay.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 46, 'Marquis de Pomereuil Brut', 'Bouteille de Champagne français brut festif et minéral.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 47, 'Marquis de Pomereuil Brut 3L', 'Bouteille format Jéroboam (3 litres) de Champagne Marquis de Pomereuil Brut pour les grandes occasions.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 48, 'Pommery Brut', 'Bouteille de Champagne de renommée mondiale, vive et ronde avec de jolies notes fruitées.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 49, 'Pommery Brut 3L', 'Bouteille format Jéroboam (3 litres) de Champagne Pommery Brut.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 50, 'Highland Park 12 ans', 'Whisky de malt d''Écosse aux notes de miel de bruyère et de tourbe fine.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 51, 'Singleton 12 ans', 'Whisky single malt écossais équilibré, doux et fruité avec des notes de noisette.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 52, 'Talisker 10 ans', 'Single malt tourbé avec des notes salines, fumées et une finale poivrée.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 53, 'Lagavulin 8 ans', 'Whisky d''Islay single malt tourbé, fumé et intense.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 54, 'Johnnie Walker XR21', 'Édition exclusive de whisky écossais assemblé de 21 ans d''âge, doux et miellé.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 55, 'Balvenie Double Wood 12 ans', 'Single malt vieilli en fûts de chêne traditionnels puis affiné en fûts de Xérès (Sherry).');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 56, 'Balvenie Port Wood 21 ans', 'Whisky exceptionnel vieilli en fûts de porto, offrant des notes riches de fruits secs et d''épices.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 57, 'Macallan 15 ans', 'Single malt d''exception vieilli en fûts de chêne ayant contenu du Sherry.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 58, 'Merlet VSOP Brothers Blend', 'Cognac français élégant aux arômes de fruits blancs et de vanille boisée.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 59, 'Don Julio Reposado', 'Tequila reposado vieillie en fûts de chêne blanc avec de délicates notes de caramel.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 60, 'Don Julio Añejo', 'Tequila añejo riche vieillie 18 mois avec des notes de caramel et de miel.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 61, 'Don Julio 1942', 'Tequila añejo légendaire, douce et onctueuse avec des notes riches de vanille et caramel.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 62, 'Clase Azul Reposado', 'Tequila d''exception douce et sucrée présentée dans sa carafe en céramique peinte à la main.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 63, 'Grey Goose', 'Vodka française haut de gamme distillée à base de blé et d''eau de source.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 64, 'Roku Gin', 'Gin artisanal japonais composé de six plantes botaniques saisonnières.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('fr', 'menu_item', 65, 'Monkey 47 (500ml)', 'Gin d''une complexité rare issu de la Forêt-Noire en Allemagne, distillé avec 47 plantes.');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 1, '西瓜のジントニック', '毎朝絞る新鮮なスイカ果汁、クラフトジン、ドライトニックウォーターを合わせ、凍らせたスイカのキューブを添えた、軽やかで爽快な夏のジントニック。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 2, 'アールグレイ・サワー', 'アールグレイを漬け込んだ華やかなジンに、新鮮なレモン果汁、野生の花のハチミツ、搾りたてのリンゴジュースをバランスよく調和させたサワーカクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 3, 'ウーロン・オールドファッションド', 'プレミアムなアメリカンバーボンウイスキーに、台湾の最高峰・阿里山の高山ウーロン茶葉を72時間かけてじっくりとコールドインフューズした、深い余韻を味わう一杯。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 4, 'パッションフルーツ・ダイキリ', 'カリブ海産のライトラム、ライム、新鮮な台湾産パッションフルーツのパルプに、台湾山間部で採れる希少なスパイス「馬告（マーガオ）」を砕き入れたトロピカルなサワー。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 5, 'グアバ・クーラー', '華やかな香りのレッドグアバ果汁、ライトラム、ライムに、自家製のキュウリとバイマックルー（コブミカンの葉）の特製シロップを加えた超爽快な一杯。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 6, '酸梅湯ウィスキーサワー', '伝統的な台湾の燻製梅スープ「酸梅湯（スアンメイタン）」をじっくりと漬け込んだウイスキーを使用。レモン、シロップ、ビターズを合わせ、仕上げにピートの効いたアイラモルトのスプレーをひと吹き。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 7, 'チョコレート・ネグローニ', '熟成されたVSOPコニャックに、店内で仕込む濃厚なダークカカオリキュール、トリプルセック、カンパリをブレンドした、贅沢な食後酒スタイル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 8, 'ウマビー', 'ドライジン、レモン、そしてスパークリングワインをじっくり煮詰めて作ったリダクションシロップをシェイクし、有機ビーポーレン（ミツバチの花粉）をあしらった一杯。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 9, 'アブサン・エメラルド', 'ジン、薬草酒アブサン、レモン、さらに日本の柚子胡椒と新鮮な大葉（しそ）をすり潰し合わせた、清涼感あふれるハーブ調カクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 10, 'エル・ディアブロ・ヴェルデ', 'メキシコ・ドゥランゴ産のクラフトメスカルの強烈なスモーキーさに、ライム、生のハラペーニョのスライス、Merletのカシスリキュールを合わせた甘辛カクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 11, '鳥梨カルヴァドス', 'リンゴのブランデー「オー・ド・ヴィー・ド・ポム」にレモンを合わせ、台湾の伝統的な砂糖漬けの小さな梨（鳥梨仔）を添えた情緒ある一杯。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 12, 'スモークゼスト＆ペッパー', '手作りのアマラス・ヴェルデ・メスカルを贅沢に使い、フレッシュなライムの酸味と、カラマンシーおよび白コショウによる爽やかでスパイシーな刺激が調和した、スモーキーで力強いカクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 13, 'タコスチップス ＆ 自家製サルサ', 'パリッと揚げたコーンナチョスに、トマト、パクチー、タマネギで毎日手作りするフレッシュサルサを添えて。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 14, '黒糖ローストナッツ', '数種類の厳選ナッツを、台湾伝統の黒糖とスパイスで店内で香ばしくローストしました。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 15, '自家製鴨の生ハム', '上質な鴨胸肉を店内で秘伝のスパイスと共に塩漬けし、じっくりと風乾熟成させた旨味の凝縮した鴨の生ハムです。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 16, 'ナチョス・プレート', 'たっぷりチーズをのせて焼き上げたコーンナチョスに、ハラペーニョ、フレッシュサルサ、サワークリームを盛り付けたシェアプレート。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 17, 'チキンと生野菜のヨーグルトロール', 'ジューシーに焼いた鶏胸肉とたっぷりのシャキシャキ野菜を、爽やかな自家製ヨーグルトソースと共にトルティーヤで巻きました。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 18, 'サーモンマリネのサワートースト', '自家製でハーブマリネしたアトランティックサーモンのスライスを、ディル風味のサワークリームを塗った香ばしいサワードゥブレンドトーストにのせて。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 19, 'アップル・オスマンサス', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 20, 'ラズベリー・ルイボス', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 21, 'パッションフルーツ・ウーロン', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 22, 'テパチェ', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 23, 'ビサップ', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 24, 'シトラス・ジェイド', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 25, 'ウーロン・スパークリング', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 26, 'レッドポイント ラガー 4.8% alc.', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 27, 'レッドポイント 台PA 5.8% alc.', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 28, 'ダーティ・マティーニ', 'ドライジンとドライベルモットを調和させ、オリーブの塩水を加えることで深みのある塩気を演出したクラシックカクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 29, 'エスプレッソ・マティーニ', '3回蒸餾のピュアウォッカに、店内のエスプレッソマシンで抽出した挽きたてのエスプレッソ、黒糖、自家製のコーヒーアマーロを合わせた贅沢な一杯。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 30, 'パロマ', '爽やかな炭酸が弾けるメキシコの国民的カクテル：テキーラ、新鮮なライム、ピンクグレープフルーツジュースにカンパリを少量加え、ソーダでアップ。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 31, 'クローバークラブ', '禁酒法以前の傑作。ジン、レモン、新鮮なラズベリーシロップ、ドライベルモットを合わせ、卵白をシェイクして極めてきめ細やかな泡の層を作ります。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 32, 'ブラッディ・メアリー', 'スパイシーでおつまみ感覚のカクテル：ウォッカ、レモン果汁、濃厚なトマトジュースに、ウスターソース、タバスコ、挽きたて黒コショウを加えた秘伝の味わい。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 33, 'ピニャ・コラーダ', 'トロピカルパラダイスを連想させる一杯。ホワイトラム、ライム、フレッシュパイナップルジュース、そして濃厚で甘いココナッツクリームをフローズン仕立てに。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 34, 'モスコミュール', 'すっきりとしたウォッカ、フレッシュなライムの酸味、そしてピリッと辛口なジンジャービアーが調和した爽快な高球（ハイボール）カクテル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 35, 'ペニシリン', '身体を温めるような温和な味わい。スコッチウイスキー、新鮮なレモン、自家製のハニージンジャーシロップを合わせ、仕上げにピートの効いたアイラシングルモルトをフロート。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 36, 'ピスコサワー', '南米ペルーの定番：ペルー産葡萄蒸留酒ピスコ、ライム果汁、シロップ、卵白をシェイクし、仕上げに芳香豊かなペルーの「アマルゴ・チュンチョ」ビターズを数滴落として。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 37, 'サゼラック', 'ニューオーリンズを代表する伝統カクテル。力強いライ麦ウイスキー、シンプルなシロップ、アロマチックなペイショーズビターズを合わせ、仕上げにグラスの内側をアブサンでリンスして独特の香りを纏わせています。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 38, 'サイドカー', '洗練された酸味と柑橘の香りが特徴の傑作カクテル。上質なコニャックに、華やかなコアントローと新鮮なレモン果汁を絶妙なバランスでシェイク。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 39, 'ビュー・カレ', 'ニューオーリンズのフランス人街に由来する複雑で重厚なクラシックカクテル。ライウイスキー、滑らかなコニャック、スイートベルモット、ベネディクティン、そしてビターズが織りなす極上の余韻。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 40, '午後の死', '文豪アーネスト・ヘミングウェイが考案したとされる強烈なシャンパンカクテル。ハーブが香るホワイトアブサンを、キリッと冷えたシャンパンで満たします。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 41, 'ハウススピリッツ ボトル', '当店の精選ハウススピリッツからお好きなボトルを1本お選びいただけます（ウォッカ、ジン、バーボンウイスキー、ライトラム、テキーラシルバー）。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 42, 'ハウスワイン（赤 / 白）', '当店が厳選したハウス赤ワインまたはハウス白ワインのボトルです。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 43, 'Château Edmus St Émilion 2013', 'フランス・ボルドー地方サンテミリオン地区の格付け赤ワイン。メルロー主体のまろやかでエレガントな味わい。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 44, 'Les Bellissands 1er Cru 2018', 'フランス・ブルゴーニュの一級畑（プルミエ・クリュ）から生まれた最高級のピノ・ノワール赤ワイン。赤い果実と繊細な樽の香り。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 45, 'Pouilly Fuissé 2018', 'フランス・ブルゴーニュ地方南部の銘醸地プイィ・フュイッセから、エレガントで辛口なシャルドネ白ワイン。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 46, 'Marquis de Pomereuil Brut', '新鮮でキリッとした心地よい酸味を持つ、お祝いの席に欠かせないフレンチシャンパンボトル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 47, 'Marquis de Pomereuil Brut 3L', 'パーティーや大人数でのお祝いに最適な、3リットルの巨大マグナム（ジェロボアム）サイズのシャンパンボトル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 48, 'Pommery Brut', '世界的に名高い「ポメリー」のクラシックなブリュットシャンパン。ふくよかで瑞々しいフルーティーなアロマ。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 49, 'Pommery Brut 3L', 'ポメリー・ブリュットの3リットル巨大マグナム（ジェロボアム）セレブレーションボトル。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 50, 'ハイランドパーク12年', 'スコットランド最北端近くで造られるシングルモルト。ヘザーハニーの甘みと穏やかなピートスモークが調和した銘酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 51, 'シングルトン12年', '非常に滑らかで飲みやすいシングルモルトスコッチウイスキー。豊かな完熟フルーツやナッツの香りが特徴。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 52, 'タリスカー10年', '個性が際立つ島産シングルモルト。潮風の塩気、スモーキーさ、そして黒コショウのようなスパイシーな余韻。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 53, 'ラガヴーリン8年', 'アイラ島を代表するシングルモルト。非常に強烈なピートの煙、潮風、そしてドライな甘みが力強く広がります。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 54, 'ジョニーウォーカー XR21年', '創業者一族の功績を称えてブレンドされた21年熟成の最高峰スコッチ。極めて滑らかで蜂蜜のような甘いアロマ。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 55, 'ザ・バルヴェニー ダブルウッド12年', '伝統的なオーク樽で熟成後、シェリー樽に移し替えて仕上げを行うダブル熟成が生み出す、豊かな蜂蜜とバニラの甘み。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 56, 'ザ・バルヴェニー ポートウッド21年', '長期熟成したモルトをポートワインの樽で追加仕上げした極上品。ドライフルーツやスパイスの濃厚な味わい。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 57, 'ザ・マッカラン ダブルカスク15年', 'シェリー樽で熟成されたアメリカンオークとヨーロピアンオークの原酒を絶妙にブレンド。温かみのあるキャラメル風味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 58, 'メルレ VSOP コニャック', '果樹園のフルーツの香りと、バニラを思わせるオーク樽の品格ある風味が調和したフランス産コニャック。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 59, 'ドン・フリオ レポサド', 'アメリカンホワイトオーク樽で8ヶ月熟成されたプレミアムテキーラ。レモンやスパイスの芳醇な香り。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 60, 'ドン・フリオ アネホ', 'オーク樽で18ヶ月じっくりと熟成。複雑なキャラメル、野生の蜂蜜、そして心地よいウッドスモークの風味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 61, 'ドン・フリオ 1942', 'ブランドの傑作。少人数への最高のおもてなしに選ばれるアネホテキーラ。温かみのあるシルクのようなバニラの甘み。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 62, 'クラセ・アズール レポサド', 'メキシコの職人が手描きした美しい青と白の陶器ボトル。味わいは非常に滑らかで、甘いバニラの風味が口に広がります。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 63, 'グレイグース ウォッカ', 'フランス産の上質な冬小麦と天然の湧水を使用し、職人技で丹念に作られる最高峰のウォッカ。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 64, 'サントリー クラフトジン 六（ROKU）', '桜、桜葉、煎茶、玉露、山椒、柚子という、日本の四季を彩る6種の和ボタニカルが織りなす繊細なクラフトジン。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('ja', 'menu_item', 65, 'モンキー 47 (500ml)', 'ドイツの「黒い森」で造られる比類なき複雑なジン。地元のボタニカルを中心に47種類もの素材を使用した深い味わい。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 1, '西瓜琴湯尼', '夏日清涼首選，將每日清晨現榨西瓜汁與工藝琴酒、乾通寧汽水結合，點綴西瓜凍製而成的原汁冰磚，口感輕盈舒爽。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 2, '伯爵蘋果酸酒', '芳香四溢的柑橘酸調酒，將伯爵茶香琴酒與新鮮檸檬、有機野花蜂蜜及現磨蘋果汁精緻調和。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 3, '烏龍古典雞尾酒', '慢飲型工藝調酒，展現優質波本威士忌與低溫慢浸72小時的阿里山高山烏龍茶葉交織的木質與茶香底蘊。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 4, '百香果黛綺麗', '滿溢熱帶酸甜感，以加勒比海白蘭姆酒、新鮮檸檬、在地百香果肉，配合現磨馬告（野生山胡椒）調製而成。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 5, '芭樂冷飲', '甜美在地紅心芭樂汁與淺色蘭姆酒、新鮮檸檬相遇，融入店內特調的小黃瓜泰國青檸葉糖漿，帶來極致清爽感。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 6, '酸梅湯威士忌酸酒', '台式情懷的完美融合，以烏梅慢火熬煮酸梅湯浸漬威士忌，佐以黃檸檬與自製糖漿，噴灑煙燻艾雷島泥煤威士忌噴霧點綴。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 7, '巧克力尼格羅尼', '奢華餐後甜點般的風味，精選橡木桶熟成 VSOP 干邑白蘭地，揉合店內特製黑巧克力利口酒、橙皮酒與金巴利。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 8, '鮮蜜蜂', '優雅清甜的極致，以乾琴酒為基底，結合黃檸檬、慢熬氣氣泡葡萄酒濃縮液，最後點綴充滿自然甜香的天然蜂花粉。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 9, '翡翠苦艾酒', '層次濃烈的草本感官盛宴，將琴酒、傳奇苦艾酒與新鮮檸檬汁相撞，添入日式柚子胡椒及現搗紫蘇葉提味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 10, '綠魔鬼', '泥土煙燻與草本辛香交融，融合墨西哥杜蘭戈梅茲卡爾龍舌蘭酒、鮮萊姆、新鮮切片墨西哥綠青椒及黑醋栗利口酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 11, '鳥梨蘋果白蘭地', '台灣在地風味演繹，以清新蘋果生命之水、黃檸檬為底，裝飾自製糖漬鳥梨仔（醃鳥梨）。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 12, '煙燻果皮與胡椒', '一款大膽的煙燻風味調酒，選用手工阿瑪拉斯綠色梅茲卡爾酒為基底，完美調和新鮮萊姆的酸度，並融入金桔與白胡椒帶來的明亮辛香微辣口感。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 13, '莎莎醬和玉米片', '酥脆美式玉米片，搭配每日自製新鮮蕃茄、洋蔥、香菜莎莎醬。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 14, '紅糖烤堅果', '精選綜合堅果，拌入台灣古早味紅糖與特色辛香料慢火烤製。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 15, '自製鴨肉風乾', '嚴選優質鴨胸肉，於店內進行秘製醃漬與自然風乾熟成，切成薄片，鹹香四溢。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 16, '玉米片拼盤', '分享大拼盤，玉米片鋪滿濃郁起司烘烤，伴有墨西哥辣椒、莎莎醬與酸奶油。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 17, '鮮蔬優格香烤雞肉捲', '香烤嫩雞胸肉搭配多種新鮮蔬菜，拌入清爽的自製優格醬，裹於薄麥餅皮中。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 18, '醃製鮭魚麵包塔佐酸奶油', '店內自醃大西洋鮭魚切片，鋪於烘烤過的酸種麵包上，並塗抹蒔蘿酸奶油。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 19, '蘋果桂花', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 20, '覆盆莓國寶茶', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 21, '百香果烏龍', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 22, '特帕切', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 23, '洛神花薄荷', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 24, '葡萄柚綠茶', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 25, '烏龍氣泡飲', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 26, '紅點鮮釀拉格 4.8% alc.', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 27, '紅點台PA 5.8% alc.', NULL);
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 28, '髒馬丁尼', '鹹香醇厚的經典，琴酒與乾香艾酒調和，融入飽滿的綠橄欖鹽水，裝飾綠橄欖。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 29, '義式咖啡馬丁尼', '濃郁提神的雞尾酒，三次蒸餾伏特加融合新鮮現萃義式濃縮咖啡、紅糖與自製咖啡苦香甜酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 30, '佩羅瑪', '清新微 carbonated 的墨西哥國民調酒，龍舌蘭酒、新鮮萊姆汁、粉紅葡萄柚汁，加少許金巴利與氣泡水。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 31, '三葉草俱樂部', '禁酒令前的優雅名作，調和琴酒、檸檬汁、新鮮覆盆子糖漿、乾香艾酒，蛋白搖盪出綿密頂冠。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 32, '血腥瑪莉', '豐富鹹香，以伏特加、檸檬汁、番茄汁，加入自製調味配方（辣醬油、塔巴斯科辣醬、現磨黑胡椒粒）。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 33, '鳳梨可樂達', '熱帶天堂風味，白蘭姆酒、萊姆汁、鮮鳳梨汁與濃郁甘甜的椰漿冰沙完美融合。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 34, '莫斯科騾子', '清爽暢快的經典高球杯，完美融合純淨伏特加、新鮮現榨萊姆汁與辛辣氣泡薑汁啤酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 35, '盤尼西林', '暖胃療癒之選，調和蘇格蘭調和威士忌、新鮮黃檸檬、自製生薑蜂蜜糖漿，最後漂浮煙燻艾雷島泥煤威士忌。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 36, '皮斯可酸酒', '南美經典，秘魯皮斯可葡萄蒸餾酒、現榨檸檬汁、糖漿、蛋白，最後滴入芳香的 Amargo Chuncho 苦精。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 37, '薩澤拉克', '新奧爾良的標誌性經典調酒，將風味濃郁的裸麥威士忌與甜美糖漿、芳香的裴喬氏苦精精妙調和，杯壁輕抹 absinthe 苦艾酒增添神秘香氣。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 38, '邊車', '高雅且酸甜平衡的經典名作，精選莫萊干邑 VSOP 白蘭地，調和清爽君度橙皮酒與新鮮檸檬汁。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 39, '老廣場', '複雜且酒感渾厚的新奧爾良致敬之作，精選裸麥威士忌、滑順的 VSOP 干邑白蘭地、甜香艾酒、廊酒與苦精調配而成。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 40, '午後之死', '由大作家海明威發明的強勁起泡酒款，將芳香優雅的白苦艾酒注入冰鎮法國香檳。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 41, '基酒整瓶', '可選本店精選基酒一整瓶，包含伏特加、琴酒、波本威士忌、淺色蘭姆酒或白龍舌蘭酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 42, '精選紅酒 / 白酒', '本店精心挑選的精選整瓶紅葡萄酒或白葡萄酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 43, 'Château Edmus St Émilion 2013', '法國聖愛美濃產區的高級波爾多紅酒，以梅洛葡萄為主導，醇厚優雅。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 44, 'Les Bellissands 1er Cru 2018', '精緻的法國勃根地一級園黑皮諾紅葡萄酒，帶有迷人的紅色水果與細緻橡木香氣。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 45, 'Pouilly Fuissé 2018', '優雅乾爽的法國勃根地南部普伊富塞產區夏多內白葡萄酒。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 46, 'Marquis de Pomereuil Brut', '清脆爽口、充滿慶祝氛圍的經典法國香檳。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 47, 'Marquis de Pomereuil Brut 3L', '3公升雙大瓶（Jeroboam）慶典規格 Marquis de Pomereuil Brut 香檳。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 48, 'Pommery Brut', '享譽世界的經典波美侯天然香檳，口感圓潤活潑，果香迷人。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 49, 'Pommery Brut 3L', '3公升雙大瓶（Jeroboam）慶典規格波美侯（Pommery）天然香檳。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 50, '高原騎士12年', '蘇格蘭最北端蒸餾廠單一麥芽威士忌，融合石楠花蜜香與細緻的煙燻泥煤味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 51, '蘇格登12年', '滑順易飲的經典蘇格蘭單一麥芽威士忌，擁有豐富的熟成水果與堅果氣息。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 52, '泰斯卡10年', '極具個性的海島型單一麥芽威士忌，煙燻泥煤與強烈的黑胡椒辛香尾韻完美結合。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 53, '樂加維林8年', '強烈而甘甜的艾雷島單一麥芽蘇格蘭威士忌，充滿濃郁的煙燻、海鹽與泥煤香氣。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 54, '約翰走路 XR 21年', '為致敬亞歷山大·華克爵士所調配的頂級調和蘇格蘭威士忌，口感滑順，蘊含黃金蜂蜜甜香。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 55, '百富雙桶12年', '經典斯貝賽單一麥芽威士忌，先於傳統橡木桶中熟成，再移至雪莉桶，賦予蜂蜜與香草甜潤感。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 56, '百富21年波特桶', '尊貴的單一麥芽威士忌，於熟成後期移至精選波特桶，帶來深色成熟水果與堅果的醇厚層次。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 57, '麥卡倫雙桶15年', '精緻雙桶熟成單一麥芽威士忌，交融美國與歐洲雪莉橡木桶，展現溫暖太妃糖與乾果風味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 58, '梅萊 VSOP 干邑', '卓越的法國干邑白蘭地，散發熟成核果與香草橡木的典雅氣息。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 59, '唐·胡立歐 Reposado', '在美國白橡木桶中陳年8個月的頂級龍舌蘭，散發淡雅柑橘、香草與微辛香氣。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 60, '唐·胡立歐 Añejo', '橡木桶陳年達18個月的經典，展現焦糖、野生蜂蜜與香烤橡木的複雜風味。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 61, '唐·胡立歐 1942', '傳奇的頂級奢華 Añejo 龍舌蘭，小批次長年陳釀，呈現極致溫暖絲滑的香草與焦糖餘韻。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 62, 'Clase Azul Reposado', '享譽全球的頂級 Reposado 龍舌蘭，盛裝於墨西哥工匠手工繪製的經典藍白陶瓷瓶中，口感極致柔滑甜潤。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 63, '灰雁伏特加', '法國頂級小麥伏特加，採用法國香檳區天然泉水精細蒸餾，純淨絲滑。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 64, '六 Roku 琴酒', '日本三得利工藝琴酒，精選櫻花、櫻花葉、煎茶、玉露、山椒、柚子等六種日式時令植物釀製。');
INSERT OR IGNORE INTO translations (locale, entity_type, entity_id, name, description) VALUES ('zh', 'menu_item', 65, '猴子 47 (500ml)', '來自德國黑森林的傳奇工藝琴酒，採用獨家 47 種珍稀草本植物蒸餾，風味複雜深邃，無可比擬。');
